using Idb.Libraries.Abstractions.Services.Indexes;

namespace Idb.Libraries.Abstractions.Options;

/// <summary>
/// Defines per-contract settings used to locate InterfaceDB assets generated by the migration tool.
/// </summary>
public interface IDbContractOptions
{
    /// <summary>
    /// Absolute or project-relative path to the folder containing contract implementations (maps to the tool's storage/implementations option).
    /// </summary>
    string? ImplementationsPath { get; }

    /// <summary>
    /// Absolute or project-relative path to the folder containing the contract interface versions.
/// </summary>
    string? ContractPath { get; }

    /// <summary>
    /// Path to the migrations directory produced by the tooling for this contract.
    /// </summary>
    string? MigrationsPath { get; }

    /// <summary>
    /// Version tag representing the currently active contract baseline (e.g., "1.0.1").
    /// </summary>
    string? ActiveVersion { get; }

    /// <summary>
    /// Repository index configurations that should be provisioned for this contract during startup.
    /// </summary>
    IRepositoryIndexConfiguration[]? Indexes { get; }

    /// <summary>
    /// Controls whether indexes are provisioned dynamically, fixed from configuration, or both.
    /// </summary>
    ContractIndexProvisioningMode IndexProvisioningMode { get; }

    /// <summary>
    /// Repository implementation used to service this contract.
    /// </summary>
    ContractRepositoryType RepositoryType { get; }
}
